public class TableParser {
    private Document doc;
    public TableParser(Document doc) {
        this.doc = doc;
    }
    public List<List<String>> tableIter() {
        List<List<String>> result = new ArrayList<>();
         Element mainDiv = doc.selectFirst("div#maincontent");
        if (mainDiv == null) {
            return result;
        }
        Element table = mainDiv.selectFirst("table");
        if (table == null) {
            return result;
        }
        for (Element tr : table.select("tr")) {
            Elements firstCol = tr.select("th");
            if (!firstCol.isEmpty()) {
                continue;
            }


            List<String> row = new ArrayList<>();
            for (Element td : tr.select("td")) {
                row.add(td.text());
            }
            result.add(row);
        }
        return result;
    }
}

public class TableParser {
    private List<List<String>> tableData;  
    private Map<String, List<Object>> neighbors;

    public TableParser(List<List<String>> tableData) {
        this.tableData = tableData;
        this.neighbors = new HashMap<>();
    }

    public void parse() {
        for (List<String> row : tableData) {
            if (row.size() != 5) continue;  
            String neighbor = row.get(0);
            String ip = row.get(1);
            try {
                float lq = Float.parseFloat(row.get(2));
                float nlq = Float.parseFloat(row.get(3));
                float etx = Float.parseFloat(row.get(4));

                List<Object> values = new ArrayList<>();
                values.add(ip);
                values.add(lq);
                values.add(nlq);
                values.add(etx);

                neighbors.put(neighbor, values);
            } catch (NumberFormatException e) {

                e.printStackTrace();
            }
        }
    }

    public Map<String, List<Object>> getNeighbors() {
        return neighbors;
    }
}

