public class ImageResizer {
    private static final int RESIZE = 800;
    public static BufferedImage resize(BufferedImage img) {
        int width = img.getWidth();
        int height = img.getHeight();
        if (width > RESIZE) {
            double scale = (double) RESIZE / width;
            int newHeight = (int) Math.floor(height * scale);

            Image tmp = img.getScaledInstance(RESIZE, newHeight, Image.SCALE_AREA_AVERAGING);
            BufferedImage resized = new BufferedImage(RESIZE, newHeight, img.getType());
            Graphics2D g2d = resized.createGraphics();
            g2d.drawImage(tmp, 0, 0, null);
            g2d.dispose();

            return resized;
        }
        return img;
    }
}

