public class FeatureSelection {

    public static class Result {
        public double[][] XSelected;
        public boolean[] mask;

        public Result(double[][] XSelected, boolean[] mask) {
            this.XSelected = XSelected;
            this.mask = mask;
        }
    }

    public static Result featureSelectionVariance(double[][] X, double threshold) {
        int nSamples = X.length;
        int nFeatures = X[0].length;

        boolean[] mask = new boolean[nFeatures];
        int selectedCount = 0;

        for (int j = 0; j < nFeatures; j++) {
            double mean = 0;
            for (int i = 0; i < nSamples; i++) {
                mean += X[i][j];
            }
            mean /= nSamples;

            double var = 0;
            for (int i = 0; i < nSamples; i++) {
                var += (X[i][j] - mean) * (X[i][j] - mean);
            }
            var /= nSamples;

            if (var > threshold) {
                mask[j] = true;
                selectedCount++;
            } else {
                mask[j] = false;
            }
        }

        double[][] XSelected = new double[nSamples][selectedCount];
        for (int i = 0; i < nSamples; i++) {
            int colIdx = 0;
            for (int j = 0; j < nFeatures; j++) {
                if (mask[j]) {
                    XSelected[i][colIdx++] = X[i][j];
                }
            }
        }

        return new Result(XSelected, mask);
    }
}

public class HDF5Initializer {

    public static H5File initHDF5(String filePath, String mode, String camType) throws Exception {
        H5File file;
        if (mode.equals("w")) {
            file = new H5File(filePath, FileFormat.CREATE);
            file.open();

            file.createGroup("dvs", null);
            file.createGroup("extra", null);

            if (camType.equals("davis")) {
                file.createGroup("aps", null);
                file.createGroup("imu", null);
