public class BaseCounter {

    public Map<String, Object> iterItems() {
        return new HashMap<>();
    }

    public Map<String, Object> toDict(String getValue) {
        Map<String, Object> result = new HashMap<>();

        for (Map.Entry<String, Object> entry : iterItems().entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            if (value instanceof BaseCounter) {
                if (getValue != null) {
                    try {
                        value = value.getClass().getField(getValue).get(value);
                    } catch (Exception e) {
                        e.printStackTrace();
                        value = null;
                    }
                }
                result.put(key, value);
            } else if (value instanceof BaseCounter) {
                result.put(key, ((BaseCounter) value).toDict(getValue));
            } else {
                result.put(key, value);
            }
        }

        return result;
    }
}

