public class TriangleMaxPath {

    private int[][] grid;
    private int[][] memo;
    private static final int UNKNOWN = Integer.MIN_VALUE;

    public TriangleMaxPath(int[][] grid) {
        this.grid = grid;
        this.memo = new int[grid.length][grid[0].length];
        for (int i = 0; i < memo.length; i++) {
            for (int j = 0; j < memo[i].length; j++) {
                memo[i][j] = UNKNOWN;
            }
        }
    }

    public int maxPathSum() {
        return dfs(0, 0);
    }

    private int dfs(int i, int j) {
        if (i == grid.length) {
            return 0;
        }

        if (memo[i][j] == UNKNOWN) {
            memo[i][j] = grid[i][j] + Math.max(dfs(i + 1, j), dfs(i + 1, j + 1));
        }

        return memo[i][j];
    }
}

public class ColorJitter {

    public static Mat korniaColorJitter(Mat img, float setting) {
        if (setting * 255 > 1) {
            Mat jittered = img.clone();

            double alpha = 1.0;
            double beta = (Math.random() * 2 - 1) * setting * 255;
            jittered.convertTo(jittered, -1, alpha, beta);

            Mat hsv = new Mat();
            Imgproc.cvtColor(jittered, hsv, Imgproc.COLOR_RGB2HSV);

            List<Mat> hsvChannels = new ArrayList<>();
            Core.split(hsv, hsvChannels);
            hsvChannels.get(1).convertTo(hsvChannels.get(1), -1, 1, (Math.random() * 2 - 1) * setting * 255);
            Core.merge(hsvChannels, hsv);

            Imgproc.cvtColor(hsv, jittered, Imgproc.COLOR_HSV2RGB);

            return jittered;
        }
        return img;
    }
}

