public class BackgroundSwapTest {

    @Test
    public void testBgSwapFast() {
        int batch = 2;
        int height = 5;
        int width = 5;
        int channels = 3;
        Random rand = new Random();

        Mat[] bg_x = new Mat[batch];
        for (int b = 0; b < batch; b++) {
            bg_x[b] = new Mat(height, width, CvType.CV_32FC3);
            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    double[] vals = new double[channels];
                    for (int c = 0; c < channels; c++) {
                        vals[c] = -1.0;
                    }
                    bg_x[b].put(i, j, vals);
                }
            }
        }

        double[] bg_y = new double[batch];
        for (int b = 0; b < batch; b++) {
            bg_y[b] = rand.nextDouble();
        }

        Mat fg = new Mat(height, width, CvType.CV_32F);
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                fg.put(i, j, 0.5 + 0.1 * rand.nextGaussian());
            }
        }

        InMemoryDataset bg = new InMemoryDataset(bg_x, bg_y);
        BackgroundSwap bgSwap = new BackgroundSwap(bg, new int[]{5, 5}, null);

        Mat spliced = bgSwap.apply(fg);
        Mat spliced1Channel = new Mat();
        Core.extractChannel(spliced, spliced1Channel, 0);

        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                double valSpliced = spliced1Channel.get(i, j)[0];
                double valFg = fg.get(i, j)[0];
                assertEquals(valSpliced <= -1, valFg <= 0.5);
            }
        }
    }
}

