public class SerialDevice {

    private OutputStream serial;

    public SerialDevice(OutputStream serial) {
        this.serial = serial;
    }

    public void cmd(int cmd, long argA, long argB) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(8); // 两个 4 字节的无符号长整型
        buffer.order(ByteOrder.LITTLE_ENDIAN);
        buffer.putInt((int) argA);
        buffer.putInt((int) argB);

        serial.write(new byte[] { (byte) cmd });
        serial.write(buffer.array());
        serial.flush();
    }
}

public class SerialDevice {

    private InputStream serial;

    public SerialDevice(InputStream serial) {
        this.serial = serial;
    }

    public long flashInit() throws IOException {
        cmd(0x03, 0, 0);

        byte[] buffer = new byte[4];
        int readBytes = serial.read(buffer);
        if (readBytes != 4) {
            throw new IOException("Failed to read 4 bytes from serial");
        }

        ByteBuffer bb = ByteBuffer.wrap(buffer);
        bb.order(ByteOrder.LITTLE_ENDIAN);
        return bb.getInt() & 0xFFFFFFFFL;  
    }

