public class FuncContainer {

    private Object wModule;
    private Object wFuncGlobals;

    public Object fgetModule(Space space) {
        if (wModule == null) {
            if (wFuncGlobals != null && !space.isW(wFuncGlobals, space.wNone())) {
                wModule = space.callMethod(wFuncGlobals, "get", space.wrap("__name__"));
            } else {
                wModule = space.wNone();
            }
        }
        return wModule;
    }

public class FuncContainer {

    public static Object descrMethodNew(Space space, Class<?> wSubtype, Object wFunction, Object wInstance, Object wClass) {
        if (space.isW(wInstance, space.wNone())) {
            wInstance = null;
        }
        Method method = space.allocateInstance(Method.class, wSubtype);
        method.init(space, wFunction, wInstance, wClass);
        return space.wrap(method);
    }

public class MethodContainer {

    private Object wFunction;
    private Object wInstance;
    private Space space;

    public Object descrMethodHash() {
        Object wResult = space.hash(wFunction);
        if (wInstance != null) {
            wResult = space.xor(wResult, space.hash(wInstance));
        }
        return wResult;
    }
}

public Object descrClassMethodGet(Space space, Object wObj, Object wKlass) {
        if (space.isW(wKlass, space.wNone())) {
            wKlass = space.type(wObj);
        }
        return space.wrap(new Method(space, wFunction, wKlass, space.wNone()));
    }

public class BuiltinFunctionContainer {

    public static Object descrBuiltinFunctionNew(Space space, Class<?> wSubtype, Object wFunc) {
        Function func = space.interpW(Function.class, wFunc);
        BuiltinFunction bltin = space.allocateInstance(BuiltinFunction.class, wSubtype);
        bltin.init(func);
        return space.wrap(bltin);
    }
}

public class Timer {

