public boolean isUpperBoundClosed() {
        if (upperCut.point == null) {
            throw new IllegalArgumentException("Range unbounded above");
        } else {
            return !upperCut.below;
        }
    }

public boolean isLowerBoundClosed() {
        if (lowerCut.point == null) {
            throw new IllegalArgumentException("Range unbounded below");
        } else {
            return lowerCut.below;
        }
    }

public boolean encloses(Range other) {
       if (other == null) {
           throw new IllegalArgumentException("Range required");
       }
       return (this.lowerCut.compareTo(other.lowerCut) <= 0) &&
              (this.upperCut.compareTo(other.upperCut) >= 0);
   }

