public class ResponseParser {

    private static final Logger logger = Logger.getLogger(ResponseParser.class.getName());

    public void parseResponse(Response response) throws IOException {
        logger.info("Saving file to download path: " + Settings.DOWNLOAD_PATH);

        try (InputStream inputStream = response.getRawStream();
             FileOutputStream outputStream = new FileOutputStream(Settings.DOWNLOAD_PATH)) {

            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                outputStream.write(buffer, 0, bytesRead);
            }
        }

        logger.info("File saved successfully");
    }
}

public List<Map<String, Object>> forwardFeatures(List<Object> features) {
    List<List<Object>> bboxList = this.bboxHead.getBboxes(features);
    List<Map<String, Object>> bboxResults = new ArrayList<>();

    for (List<Object> bboxItem : bboxList) {
        List<Object> detBboxes = (List<Object>) bboxItem.get(0);
        List<Integer> detLabels = (List<Integer>) bboxItem.get(1);
        Map<String, Object> result = bbox2result(detBboxes, detLabels, this.bboxHead.getNumClasses());
        bboxResults.add(result);
    }

    return bboxResults.isEmpty() ? new ArrayList<>() : Arrays.asList(bboxResults.get(0));
}

private Map<String, Object> bbox2result(List<Object> detBboxes, List<Integer> detLabels, int numClasses) {
    Map<String, Object> result = new HashMap<>();
    result.put("bboxes", detBboxes);
    result.put("labels", detLabels);
    result.put("num_classes", numClasses);
    return result;
}

