public class CalendarHelper {

    public static long[] getCalendar(TradingCalendar tradingCalendar, BarReader reader) {
        long[] allMinutes = tradingCalendar.getAllMinutes();
        int start = searchSorted(allMinutes, reader.getFirstTradingDay(), false);
        int end = searchSorted(allMinutes, reader.getLastAvailableDt(), true);
        return Arrays.copyOfRange(allMinutes, start, end);
    }

    private static int searchSorted(long[] array, long value, boolean sideRight) {
        int low = 0;
        int high = array.length;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (array[mid] < value || (sideRight && array[mid] == value)) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

