public class DateFormatter {

    public static String getDateFormatted(ZonedDateTime dt, boolean isAllDay) {
        if (isAllDay) {
            return dt.format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
        } else {
            return dt.format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSSZ"));
        }
    }
}

public class ImageUtils {

    public static int getImageIdFromFileName(String filename, int idIter) {

        String nameWithoutExt = filename.contains(".") 
            ? filename.substring(0, filename.lastIndexOf('.')) 
            : filename;

        if (nameWithoutExt.matches("\\d+")) {  
            return Integer.parseInt(nameWithoutExt);
        }

        return idIter;
    }
}

public class AnnotationParser {

    public static List<List<Integer>> annoParser(List<String> annosStr) {
        List<List<Integer>> annos = new ArrayList<>();

        for (String annoStr : annosStr) {
            String[] parts = annoStr.trim().split(",");
            List<Integer> anno = new ArrayList<>();
            for (String part : parts) {
                anno.add(Integer.parseInt(part));
            }
            annos.add(anno);
        }

        return annos;
    }
}

