public Object setMarginMode(String marginType, String symbol, Map<String, Object> params) throws Exception {
    marginType = marginType.toUpperCase();
    if (!marginType.equals("ISOLATED") && !marginType.equals("CROSSED")) {
        throw new BadRequest(this.id + " marginType must be either isolated or crossed");
    }

    this.loadMarkets();
    Map<String, Object> market = this.market(symbol);
    String method = null;

    if ((boolean) market.get("linear")) {
        method = "fapiPrivatePostMarginType";
    } else if ((boolean) market.get("inverse")) {
        method = "dapiPrivatePostMarginType";
    } else {
        throw new NotSupported(this.id + " setMarginMode() supports linear and inverse contracts only");
    }

    Map<String, Object> request = new HashMap<>();
    request.put("symbol", market.get("id"));
    request.put("marginType", marginType);

    Map<String, Object> extendedRequest = this.extend(request, params);


    return this.invokeMethodByName(method, extendedRequest);
}

